import {ITEMS} from './repertoire.js?v=5.38';
import {GOODS,CIVIC_WORKS,RECIPES,STAMPS,economyState,economyRegion,district,marketInfo,quoteSupply,purchaseSupply,commodityQuote,tradeGood,localNeed,fulfillNeed,civicCost,buildCivic,craftSupply,routeOffer,acceptShipment,cancelShipment,deliverShipment,tradeAllowed,districtName} from './economy.js?v=5.18.0';
const el=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n;};
export function economyPanel({world,merchant=null,onSave=()=>{},onBack=()=>{}}){const root=el('section','economy-panel');let useFavor=false,receipt='',filter='all';const r=economyRegion(world),s=world.state;const near=()=>!!merchant&&world.scene.location===merchant.scene&&Math.hypot(s.x-merchant.xy[0]-.5,s.y-merchant.xy[1]-.5)<2.1;const can=()=>tradeAllowed(s)&&near();
 function button(label,action,enabled=true){const b=el('button','',label);b.disabled=!enabled;b.onclick=()=>{if(!can())return;const ok=action();receipt=ok?'Applied · '+(economyState(s).history[0]||label):'That exchange is unavailable. No resources were spent.';onSave();paint();};return b;}
 function paint(){const e=economyState(s),d=district(s,r),m=marketInfo(s,r);root.replaceChildren();const top=el('header','economy-header');top.append(el('small','','THE COMMON EXCHANGE'),el('h3','',m.name),el('p','',s.gold+' credits · '+d.favor+' local reciprocity · '+m.prosperity+' community improvements · '+(d.reserve||0)+' credits in the shared reserve'));const close=el('button','', 'Back to the road');close.onclick=onBack;top.append(close);root.append(top);const wallet=el('div','economy-wallet');for(const g of GOODS){const n=el('div','economy-good');n.style.setProperty('--good',g.color);n.append(el('b','',g.glyph+' '+e.goods[g.id]),el('small','',g.name));wallet.append(n);}root.append(wallet);const notice=el('p','economy-receipt',receipt||(can()?'Trade here. Each purchase shows its full cost before you commit.':'Your trade satchel · visit a merchant to exchange goods. Credits travel everywhere; reciprocity belongs to the district that earned it.'));notice.setAttribute('role','status');root.append(notice);
 const grid=el('div','economy-grid');const needs=el('section','economy-card'),n=localNeed(s,r),good=GOODS.find(g=>g.id===n.id);needs.append(el('h4','','Neighbours need '+good.name.toLowerCase()),el('p','',n.quantity+' bundles → '+n.credits+' credits + 3 local reciprocity. '+n.left+' requests remain this chapter.'),el('small','','The materials go to local households and makers. Reciprocity can reduce a later supply purchase by 20%.'));needs.append(button('Deliver '+n.quantity+' '+good.name,()=>fulfillNeed(s,r),can()&&n.left>0&&e.goods[n.id]>=n.quantity));grid.append(needs);
 const trade=el('section','economy-card');trade.append(el('h4','','Materials travel. Their value changes.'),el('p','','Local surplus: '+GOODS.find(g=>g.id===m.exportGood).name+'. Needed here: '+good.name+'. Your satchel carries goods between actual regions.'));for(const g of GOODS){const q=commodityQuote(s,r,g.id),row=el('div','economy-row');row.append(el('strong','',g.glyph+' '+g.name),button('Buy '+q.buy+' · '+q.exportLeft+' left',()=>tradeGood(s,r,g.id,'buy'),can()&&q.exportLeft>0&&s.gold>=q.buy),button('Sell '+q.sell+' · '+q.importLeft+' wanted',()=>tradeGood(s,r,g.id,'sell'),can()&&q.importLeft>0&&e.goods[g.id]>0));trade.append(row);}grid.append(trade);
 const cargo=el('section','economy-card'),offer=routeOffer(s,r);cargo.append(el('h4','','Protected consignments'),el('p','',offer.label+(offer.destination>s.chapter?' · Opens in chapter '+offer.destination:'')+' · '+offer.quantity+' '+offer.good+' → '+offer.credits+' credits. Win two different real encounters while carrying the cargo, then deliver to a merchant at the destination.'));cargo.append(button('Load this consignment',()=>acceptShipment(s,r),can()&&offer.available&&e.goods[offer.good]>=offer.quantity&&e.shipments.length<(e.stamps.includes('three-hands')?2:1)));for(const q of e.shipments){cargo.append(el('p','',q.label+' · protected '+q.protected+'/2'),button('Deliver cargo · '+q.credits,()=>deliverShipment(s,r,q.id),can()&&q.destination===r&&q.protected>=2));const cancel=el('button','','Unpack cargo · return materials');cancel.disabled=!tradeAllowed(s);cancel.onclick=()=>{if(cancelShipment(s,q.id)){receipt='Cargo unpacked. Materials returned.';onSave();paint();}};cargo.append(cancel);}grid.append(cargo);
 const civic=el('section','economy-card');civic.append(el('h4','','Build something the town keeps'));for(const work of CIVIC_WORKS){const q=civicCost(s,r,work.id);civic.append(el('strong','',q.done?'✓ '+work.name:work.name),el('p','',work.text+(q.match?' The shared reserve contributes '+q.match+' credits to this work.':'')),button(q.done?'Open for everyone':q.credits+' credits + '+q.quantity+' '+q.good,()=>buildCivic(s,r,work.id),can()&&!q.done&&s.gold>=q.credits&&e.goods[q.good]>=q.quantity));}grid.append(civic);
 const craft=el('section','economy-card');craft.append(el('h4','','Turn salvage into battle choices'));for(const recipe of RECIPES.filter(v=>v.chapter<=s.chapter)){const cost=Math.max(1,recipe.cost-(d.works.includes('workshop')?1:0));craft.append(button(recipe.name+' · '+cost+' '+recipe.good+' → '+ITEMS.find(i=>i.id===recipe.item).name,()=>craftSupply(s,r,recipe),can()&&e.goods[recipe.good]>=cost));}grid.append(craft);root.append(grid);
 const shop=el('section','economy-shop');shop.append(el('h4','','Outfit your next encounter'));const controls=el('div','economy-row');const favor=el('button','',useFavor?'✓ Spend 2 local reciprocity for 20% off':'Use local reciprocity for a discount');favor.setAttribute('aria-pressed',String(useFavor));favor.onclick=()=>{useFavor=!useFavor;paint();};controls.append(favor);const select=el('select');select.setAttribute('aria-label','Supply category');for(const [id,label]of [['all','All supplies'],['field','Restoration'],['battle','Battle tools']]){const o=el('option','',label);o.value=id;o.selected=id===filter;select.append(o);}select.onchange=()=>{filter=select.value;paint();};controls.append(select);shop.append(controls);const items=el('div','economy-items');for(const item of ITEMS.filter(i=>i.chapter<=s.chapter&&(filter==='all'||(filter==='field')===/heal|mp|revive|cleanse/i.test(i.effect)))){const q=quoteSupply(s,r,item,useFavor),card=el('article','economy-item');card.append(el('strong','',item.name),el('p','',item.description),el('small','',(q.remaining===Infinity?'Reliable stock':q.remaining+' available this chapter')+' · carrying '+(s.items[item.id]||0)),button('Buy · '+q.price+' credits'+(q.favorCost?' + '+q.favorCost+' reciprocity':''),()=>purchaseSupply(s,r,item,useFavor),can()&&q.remaining>0&&s.gold>=q.price));items.append(card);}shop.append(items);root.append(shop);
 const book=el('details','economy-book');book.append(el('summary','','Your roads, seals and community accounts'));for(const stamp of STAMPS)book.append(el('p','', (e.stamps.includes(stamp.id)?'✦ ':'◇ ')+stamp.name+' · '+Math.min(stamp.at,e.delivered.length)+'/'+stamp.at+' shipments · '+stamp.text));if(e.heritageWorks)book.append(el('p','','Your previous lineage built '+e.heritageWorks+' public works. Its seals survive; this era rebuilds its own services.'));book.append(el('p','',e.flow.earned+' credits earned through trade · '+e.flow.spent+' spent · '+e.flow.public+' directed into local services. These are transaction records, not simulated population or household wealth.'));for(const [id,town]of Object.entries(e.districts).filter(([,v])=>v.favor||v.works.length))book.append(el('p','',districtName(Number(id))+' · '+town.favor+' reciprocity · '+town.works.length+' public works'));for(const line of e.history)book.append(el('p','',line));book.append(el('p','','Ten percent of exchange supply purchases enters this district’s shared reserve, which can match up to 25% of a public project’s credit cost. Supply and material quotas renew when the main story chapter advances. Resting, changing time, saving and reopening a shop do not refill them. No streaks, countdown pressure or interest debt. Main-story healing and rest stay available.'));root.append(book);
 }paint();return root;}
